{
  "mcpServers": {
    "aitmpl": {
      "description": "Official MCP server of the aitmpl.com catalog: lets Claude search Claude Code components (agents, commands, skills, hooks, MCP servers, settings, loops, mods and plugins), read one with its full content and SkillSpector scan, and get the claude-code-templates command that installs it. It also serves two skills over MCP (Claude Code 2.1.331 or later): component-review and skill-over-mcp. Remote, read-only, no sign-in; it installs nothing itself, Claude runs the returned command.",
      "type": "http",
      "url": "https://mcp.aitmpl.com/mcp"
    }
  },
  "mcpTools": {
    "aitmpl": [
      {
        "name": "search_components",
        "title": "Search aitmpl components",
        "description": "Search the catalog by text and get each match's id, description, page, install command and SkillSpector scan, ordered by how well the text matches.",
        "readOnly": true
      },
      {
        "name": "get_component",
        "title": "Get an aitmpl component",
        "description": "Return one component by id with its full content, the files it ships, what it writes on install, its license and source, and its SkillSpector scan.",
        "readOnly": true
      },
      {
        "name": "get_install_command",
        "title": "Get the install command",
        "description": "Return the single claude-code-templates command that installs up to 20 components into the current project.",
        "readOnly": true
      },
      {
        "name": "list_categories",
        "title": "List aitmpl categories",
        "description": "List the component types with their counts, and the categories of one type or all types.",
        "readOnly": true
      }
    ]
  },
  "mcpSkills": {
    "aitmpl": [
      {
        "name": "component-review",
        "description": "Review a Claude Code component (agent, command, skill, hook, MCP server config or setting) before sharing it or sending it to aitmpl.com."
      },
      {
        "name": "skill-over-mcp",
        "description": "Build an MCP server that serves skills (Skills over MCP, extension io.modelcontextprotocol/skills) with the official TypeScript SDK."
      }
    ]
  }
}
